import { rawBatch } from './query';

// Migrations generated by drizzle-kit (`pnpm db:generate`), bundled as text.
// The default drizzle migrator reads from the filesystem and therefore doesn't work on Workers.
const migrations = import.meta.glob<string>('/drizzle/*.sql', {
	query: '?raw',
	import: 'default',
	eager: true
});

export async function migrate() {
	// One round-trip: this runs on the first request of every isolate.
	const [, rows] = await rawBatch([
		{
			sql: 'CREATE TABLE IF NOT EXISTS __migrations (name TEXT PRIMARY KEY, applied_at INTEGER NOT NULL)'
		},
		{ sql: 'SELECT name FROM __migrations' }
	]);
	const applied = new Set(rows.map(([name]) => name));

	for (const [path, sql] of Object.entries(migrations).sort(([a], [b]) => a.localeCompare(b))) {
		const name = path.split('/').pop()!;

		if (applied.has(name)) {
			continue;
		}

		// A migration and its row in `__migrations` run as one batch, which D1 runs as a transaction:
		// a request that is cut off or races another isolate applies all of it or nothing, so the next
		// request can simply try again. It is also one round-trip per migration instead of one per
		// statement, which matters on a fresh install, before the Worker has its D1 bindings.
		await rawBatch([
			...sql
				.split('--> statement-breakpoint')
				.filter((statement) => statement.trim())
				.map((statement) => ({ sql: statement })),
			{
				sql: 'INSERT INTO __migrations (name, applied_at) VALUES (?, ?)',
				params: [name, Date.now()]
			}
		]);
	}
}
